<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use Illuminate\Validation\ValidationException;
class FrontOfficeController extends Controller {
 private const TYPES=['Parent / Guardian','Admission Enquiry','Vendor','Official','Other'];
 private function scope(string $permission){ $u=auth()->user(); abort_unless($u && $u->school_id && $u->can('front-office.'.$permission),403); return DB::table('front_office_visits')->where('school_id',$u->school_id); }
 private function today(){return now('Asia/Kolkata')->toDateString();}
 public function index(Request $r){ $q=$this->scope('view'); $v=$r->validate(['date'=>'nullable|date_format:Y-m-d']); $date=$v['date']??$this->today(); $q->where('visit_date',$date); $stats=(clone $q)->selectRaw("COUNT(*) AS entries, COALESCE(SUM(team_size),0) AS people, SUM(CASE WHEN visitor_type='Parent / Guardian' THEN 1 ELSE 0 END) AS parents, SUM(CASE WHEN out_time IS NULL THEN 1 ELSE 0 END) AS open_entries, SUM(CASE WHEN out_time IS NOT NULL THEN 1 ELSE 0 END) AS closed_entries")->first(); $visits=$q->orderByDesc('in_time')->orderByDesc('id')->paginate(30)->withQueryString(); return view('front-office.index',compact('date','stats','visits')); }
 public function create(){ $this->scope('create'); return view('front-office.form',['visit'=>null,'types'=>self::TYPES,'today'=>$this->today(),'time'=>now('Asia/Kolkata')->format('H:i')]); }
 private function data(Request $r){return $r->validate(['visit_date'=>['required','date_format:Y-m-d','before_or_equal:'.$this->today()],'in_time'=>'required|date_format:H:i','out_time'=>'nullable|date_format:H:i|after_or_equal:in_time','visitor_name'=>'required|string|max:255','mobile'=>'nullable|string|max:30','visitor_type'=>['required',Rule::in(self::TYPES)],'team_size'=>'required|integer|min:1|max:1000','meet_person'=>'required|string|max:255','student_name'=>'nullable|string|max:255','purpose'=>'required|string|max:2000','remarks'=>'nullable|string|max:2000']);}
 public function store(Request $r){$this->scope('create'); $v=$this->data($r); DB::table('front_office_visits')->insert($v+['school_id'=>auth()->user()->school_id,'created_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]); return redirect()->route('front-office.index',['date'=>$v['visit_date']])->with('success','Visitor saved.');}
 public function edit($id){$visit=$this->scope('edit')->where('id',$id)->first(); abort_unless($visit,404); return view('front-office.form',['visit'=>$visit,'types'=>self::TYPES,'today'=>$this->today(),'time'=>now('Asia/Kolkata')->format('H:i')]);}
 public function update(Request $r,$id){$q=$this->scope('edit')->where('id',$id); abort_unless((clone $q)->exists(),404); $v=$this->data($r); $q->update($v+['updated_at'=>now()]); return redirect()->route('front-office.index',['date'=>$v['visit_date']])->with('success','Visitor updated.');}
 public function checkout($id){$q=$this->scope('edit')->where('id',$id); DB::transaction(function()use($q){$visit=(clone $q)->lockForUpdate()->first(); abort_unless($visit,404); if($visit->out_time!==null)return; $time=now('Asia/Kolkata')->format('H:i:s'); if($visit->visit_date!==$this->today() || $time<$visit->in_time) throw ValidationException::withMessages(['out_time'=>'Use Edit to enter the actual checkout time for this visit.']); $q->update(['out_time'=>$time,'updated_at'=>now()]);}); return back()->with('success','Checkout recorded.');}
 public function report(Request $r){$q=$this->scope('view'); $v=$r->validate(['from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d']); $from=$v['from']??now('Asia/Kolkata')->startOfMonth()->toDateString(); $to=$v['to']??$this->today(); if($from>$to)throw ValidationException::withMessages(['to'=>'End date must be on or after start date.']); $rows=$q->whereBetween('visit_date',[$from,$to])->selectRaw("visit_date, COUNT(*) AS entries, SUM(team_size) AS people, SUM(CASE WHEN visitor_type='Parent / Guardian' THEN 1 ELSE 0 END) AS parents")->groupBy('visit_date')->orderByDesc('visit_date')->get(); return view('front-office.report',compact('rows','from','to'));}
}
